questionvariables.text:
mean:(rand(14)+3)/2;
if not(integerp(mean)) then mean:float(mean);

prob_min_a:rationalize((rand(3)+2)*mean);
prob_min_a_disp:if integerp(prob_min_a) then prob_min_a elseif integerp(1000*prob_min_a) then float(prob_min_a) else decimalplaces(prob_min_a,2);

prob_min_b:(rand(4)+2)*rationalize(mean)/10;
prob_min_b_disp:if integerp(prob_min_b) then prob_min_b elseif integerp(1000*prob_min_b) then float(prob_min_b) else decimalplaces(prob_min_b,2);

prob_max_b:(rand(4)+6)*rationalize(mean)/10;
prob_max_b_disp:if integerp(prob_max_b) then prob_max_b elseif integerp(1000*prob_max_b) then float(prob_max_b) else decimalplaces(prob_max_b,2);

mean_recip:1/mean;
mean_recip_disp:if integerp(mean_recip) then mean_recip elseif integerp(1000*mean_recip) then float(mean_recip) else decimalplaces(mean_recip,2);

ta_1:e^(-prob_min_a/rationalize(mean));
ta_2:e^(-prob_min_b/rationalize(mean))-e^(-prob_max_b/rationalize(mean));
